Here's an example implementation:

```java
import java.util.*;

class ColorCount {
    private int count;
    private String color;

    public ColorCount(int count, String color) {
        this.count = count;
        this.color = color;
    }

    public int getCount() {
        return count;
    }

    public String getColor() {
        return color;
    }
}

public class Main {
    public static ColorCount mostPopularColor(List<Car> cars) {
        // Create a HashMap to store the count of each color
        Map<String, Integer> colorCount = new HashMap<>();

        // Count occurrences of each color
        for (Car car : cars) {
            String color = car.getColor();
            colorCount.put(color, colorCount.getOrDefault(color, 0) + 1);
        }

        // Find the color with the maximum count
        Optional<Map.Entry<String, Integer>> maxEntry = colorCount.entrySet().stream()
                .max((entry1, entry2) -> entry1.getValue().compareTo(entry2.getValue()));

        // Return the count and color
